// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint64 timeOffset, uint256 blockNumber) public {
        vm.assume(amount == 10 ether);
        vm.assume(timeOffset > 0);
        vm.assume(blockNumber % 15 != 0);
        vm.deal(address(this), amount);
        vm.warp(block.timestamp + timeOffset);
        vm.roll(blockNumber);
        uint256 balanceBefore = address(c).balance;
        (bool success, ) = address(c).call{value: amount}("");
        assertTrue(success);
        uint256 expectedBalance = balanceBefore + amount;
        assertTrue(address(c).balance == expectedBalance);
    }
}

